# Generated by build.py from recipe.yml for recipe scp-pin-the-host-key. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
cmd /c 'ssh-keygen -t rsa -b 3072 -N "" -f host_key'
cmd /c 'ssh-keygen -lf host_key.pub > fingerprint.txt'
$server0 = Start-Process surl -ArgumentList '-v', '--directory', 'site', '--hostkey', 'host_key', '--user', 'alice:s3cret', 'scp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -u alice:s3cret --variable "host_sha256[12-54]@fingerprint.txt" --expand-hostpubsha256 "{{host_sha256}}" scp://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
